insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field) values
('area:grand-massif','meta','line',0,'Grand Massif | Linked ski areas | Snow Catchers','{}'::text[],'review','loader','title'),
('area:grand-massif','meta','line',1,'How Flaine, Les Carroz, Morillon, Samoëns and Sixt share one lift network, which base reaches which slopes, how much snow falls at the height of the bowl and of the villages, which pass to buy, and what the area is like for boarders, families, food and evenings.','{}'::text[],'review','loader','description'),
('area:grand-massif','meta','line',2,'France','{}'::text[],'review','loader','crumbs.0.label'),
('area:grand-massif','meta','line',3,'Linked ski areas','{}'::text[],'review','loader','crumbs.1.label'),
('area:grand-massif','meta','line',4,'Northern Alps','{}'::text[],'review','loader','crumbs.2.label'),
('area:grand-massif','hero','lead',0,'The Grand Massif joins five resorts on one lift network above the Arve and Giffre valleys of Haute-Savoie, from the purpose built bowl of Flaine down to the old stone villages of Samoëns and Morillon near the valley floor. Alti-Mag counts {{f:F000644}} of piste between {{f:F000654|n}} and {{f:F000655}}, and the longest run, the Piste des Cascades, carries skiers {{f:F000678}} from the top of Flaine to Sixt-Fer-à-Cheval. Flaine and Samoëns were first linked through the Combe de Vernant in {{f:F000669}}, and the five resorts have shared one network since {{f:F000670}}.',array['F000644','F000654','F000655','F000669','F000670','F000678']::text[],'review','loader','hero.lead'),
('area:grand-massif','stats','line',0,'{{f:F000644}}',array['F000644']::text[],'review','loader','stats.0.v'),
('area:grand-massif','stats','line',1,'of piste across five linked resorts, the figure Alti-Mag and skiresort.com share','{}'::text[],'review','loader','stats.0.t'),
('area:grand-massif','stats','line',2,'{{f:F000654|n}} to {{f:F000655}}',array['F000654','F000655']::text[],'review','loader','stats.1.v'),
('area:grand-massif','stats','line',3,'from the valley floor at Morillon to the top of the Grandes Platières cable car above Flaine','{}'::text[],'review','loader','stats.1.t'),
('area:grand-massif','stats','line',4,'{{f:F000678}}',array['F000678']::text[],'review','loader','stats.2.v'),
('area:grand-massif','stats','line',5,'down the Piste des Cascades from the Grandes Platières to Sixt, with the skibus back to Samoëns','{}'::text[],'review','loader','stats.2.t'),
('area:grand-massif','stats','line',6,'{{f:F000533}}',array['F000533']::text[],'review','loader','stats.3.v'),
('area:grand-massif','stats','line',7,'for six days, adult, 2026/27, or {{f:F000704}} for the four villages without Flaine',array['F000704']::text[],'review','loader','stats.3.t'),
('area:grand-massif','network','heading',0,'Five resorts round one high bowl','{}'::text[],'review','loader','network.h2'),
('area:grand-massif','network','para',0,'Flaine sits in a limestone bowl at the southern end of the area, its lifts climbing from {{f:F000727}} to {{f:F000728}} at the top of the Grandes Platières cable car. Les Carroz lies west of it on a sunny shelf above the Arve, Morillon and Samoëns lie north in the Giffre valley, and Sixt sits furthest east at the head of the same valley. The five meet on the high ground between Flaine and the Tête des Saix, where the lifts from Les Carroz, Morillon and Samoëns top out between {{f:F000743|n}} and {{f:F000738}} above the Saix plateau.',array['F000727','F000728','F000738','F000743']::text[],'review','loader','network.paras.0'),
('area:grand-massif','network','para',1,'Each valley village has one main way up. Samoëns climbs from the edge of the village to Samoëns 1600 by the Grand Massif Express gondola, opened in {{f:F000671}}, with the Vercland gondola as a second way in further up the valley. Morillon rides its gondola to Morillon 1100 and then the Sairon chair, and Les Carroz has the Kédeuze gondola. In the map data a closed Kédeuze gondola leaves Les Carroz village with no lift route to any of the other {{f:F000806|w}} resorts, and the Morillon gondola and the Sairon chair hold the same place for Morillon, so on a windy day the bus or the car is the way round.',array['F000671','F000806']::text[],'review','loader','network.paras.1'),
('area:grand-massif','network','para',2,'Sixt is the exception. Its four short drags serve the beginner slopes at Salvagny and do not link to the rest by lift. The way in on skis is the Piste des Cascades, {{f:F000678}} from the top of Flaine through a nature reserve to the village, and the way out is the free skibus to the Grand Massif Express in Samoëns, about eight kilometres down the valley. The Cascades ends below 800 m and needs snow all the way down, and Mon séjour en montagne reports that it stayed shut through 2023/24 and opened on less than a tenth of the days the season before.',array['F000678']::text[],'review','loader','network.paras.2'),
('area:grand-massif','network','para',3,'Skiing here began in the valley villages. Les Carroz opened its first lift in {{f:F000665}} and Samoëns its first in {{f:F000666}}. Éric and Sylvie Boissonnas found the site of Flaine in {{f:F000667}} and asked the Bauhaus architect Marcel Breuer to design a resort, which opened in {{f:F000668}}. The Combe de Vernant joined Flaine to Samoëns in {{f:F000669}}, and the Grand Massif took its present shape in {{f:F000670}}. The newest big lifts are the Coulouvrier chair above Morillon, built for {{f:F000672}}, and the ten seat Vercland gondola, ready for {{f:F000673}}.',array['F000665','F000666','F000667','F000668','F000669','F000670','F000672','F000673']::text[],'review','loader','network.paras.3'),
('area:grand-massif','network','line',0,'{{m:all.samoens.flaine}} lift rides','{}'::text[],'review','loader','network.figs.0.v'),
('area:grand-massif','network','line',1,'from Samoëns village to Flaine, and {{m:all.flaine.samoens|w}} back','{}'::text[],'review','loader','network.figs.0.t'),
('area:grand-massif','network','line',2,'{{m:all.carroz.flaine}} lift rides','{}'::text[],'review','loader','network.figs.1.v'),
('area:grand-massif','network','line',3,'from Les Carroz to Flaine, by the Kédeuze gondola and the Tête des Saix chair','{}'::text[],'review','loader','network.figs.1.t'),
('area:grand-massif','network','line',4,'{{f:F000678}}',array['F000678']::text[],'review','loader','network.figs.2.v'),
('area:grand-massif','network','line',5,'down the Piste des Cascades to Sixt, with no lift back','{}'::text[],'review','loader','network.figs.2.t'),
('area:grand-massif','network','line',6,'{{m:all.morillon.sixt}} lift rides','{}'::text[],'review','loader','network.figs.3.v'),
('area:grand-massif','network','line',7,'from Morillon to Sixt, the longest trip between villages','{}'::text[],'review','loader','network.figs.3.t'),
('area:grand-massif','network','line',8,'{{f:F000669}}',array['F000669']::text[],'review','loader','network.figs.4.v'),
('area:grand-massif','network','line',9,'the Combe de Vernant links Samoëns and Flaine','{}'::text[],'review','loader','network.figs.4.t'),
('area:grand-massif','network','line',10,'{{f:F000671}}',array['F000671']::text[],'review','loader','network.figs.5.v'),
('area:grand-massif','network','line',11,'the Grand Massif Express opens above Samoëns','{}'::text[],'review','loader','network.figs.5.t'),
('area:grand-massif','network','heading',1,'Explore the network','{}'::text[],'review','loader','network.mapTitle'),
('area:grand-massif','network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other resort, then limit the runs to see what stays within reach.','{}'::text[],'review','loader','network.mapHelp'),
('area:grand-massif','network','caption',1,'Schematic, not to scale, with the resorts moved apart for legibility. Drawn from OpenStreetMap lift and piste data (© OpenStreetMap contributors, October 2026) with heights from the Copernicus 90 m elevation model. Lift rides are the fewest needed from the village lifts of one resort to the first lift of another. The dotted line is the free skibus between Sixt and Samoëns; the Cascades runs one way, from Flaine to Sixt.','{}'::text[],'review','loader','network.caption'),
('area:grand-massif','network','line',12,'Grandes Platières','{}'::text[],'review','loader','mapNotes.0.text'),
('area:grand-massif','network','line',13,'Tête des Saix','{}'::text[],'review','loader','mapNotes.1.text'),
('area:grand-massif','routes','heading',0,'Six sample days','{}'::text[],'review','loader','routes.h3'),
('area:grand-massif','routes','line',0,'Each trip is counted in lift rides out and back from the village lifts, with the easiest grade of run that makes it in the map data. Time on the pistes, in queues, on foot and on the bus is not included.','{}'::text[],'review','loader','routes.intro'),
('area:grand-massif','routes','line',1,'Samoëns','{}'::text[],'review','loader','routes.rows.0.from'),
('area:grand-massif','routes','line',2,'Flaine','{}'::text[],'review','loader','routes.rows.0.to'),
('area:grand-massif','routes','line',3,'Red home, or blue with more lifts','{}'::text[],'review','loader','routes.rows.0.grade'),
('area:grand-massif','routes','note',0,'Up the Grand Massif Express and the Chariande Express; home by the Grandes Platières and the Combe de Vernant, or on blue by the Grand Vans and Corbalanche chairs.','{}'::text[],'review','loader','routes.rows.0.note'),
('area:grand-massif','routes','line',4,'Les Carroz','{}'::text[],'review','loader','routes.rows.1.from'),
('area:grand-massif','routes','line',5,'Flaine','{}'::text[],'review','loader','routes.rows.1.to'),
('area:grand-massif','routes','line',6,'Green and blue','{}'::text[],'review','loader','routes.rows.1.grade'),
('area:grand-massif','routes','note',1,'Kédeuze gondola and Tête des Saix chair out; home by the Grand Vans chair and down to Les Molliets.','{}'::text[],'review','loader','routes.rows.1.note'),
('area:grand-massif','routes','line',7,'Morillon','{}'::text[],'review','loader','routes.rows.2.from'),
('area:grand-massif','routes','line',8,'Samoëns','{}'::text[],'review','loader','routes.rows.2.to'),
('area:grand-massif','routes','line',9,'Green and blue','{}'::text[],'review','loader','routes.rows.2.grade'),
('area:grand-massif','routes','note',2,'Out by the gondola, the Sairon chair and the Coulouvrier chair; home from Samoëns by the Vercland gondola and the runs down to Morillon.','{}'::text[],'review','loader','routes.rows.2.note'),
('area:grand-massif','routes','line',10,'Les Carroz','{}'::text[],'review','loader','routes.rows.3.from'),
('area:grand-massif','routes','line',11,'Morillon','{}'::text[],'review','loader','routes.rows.3.to'),
('area:grand-massif','routes','line',12,'Green and blue','{}'::text[],'review','loader','routes.rows.3.grade'),
('area:grand-massif','routes','note',3,'Kédeuze gondola and the Gron chair out; the gondola and the Sairon chair home.','{}'::text[],'review','loader','routes.rows.3.note'),
('area:grand-massif','routes','line',13,'Flaine','{}'::text[],'review','loader','routes.rows.4.from'),
('area:grand-massif','routes','line',14,'Sixt','{}'::text[],'review','loader','routes.rows.4.to'),
('area:grand-massif','routes','line',15,'Red','{}'::text[],'review','loader','routes.rows.4.grade'),
('area:grand-massif','routes','note',4,'Up the Grandes Platières and down the Cascades; home by the skibus to Samoëns, the Grand Massif Express and the Chariande Express.','{}'::text[],'review','loader','routes.rows.4.note'),
('area:grand-massif','routes','line',16,'Morillon','{}'::text[],'review','loader','routes.rows.5.from'),
('area:grand-massif','routes','line',17,'Sixt','{}'::text[],'review','loader','routes.rows.5.to'),
('area:grand-massif','routes','line',18,'Red, or blue with one more lift','{}'::text[],'review','loader','routes.rows.5.grade'),
('area:grand-massif','routes','note',5,'Over the Saix plateau to Samoëns 1600 and down to the valley, then the skibus; home by the skibus and the Vercland gondola.','{}'::text[],'review','loader','routes.rows.5.note'),
('area:grand-massif','routes','note',6,'Green and blue reach every resort from every other in the map data. The reds that matter are the Cascades, graded red for its length, and the quick way from Flaine down the Combe de Vernant: on blue the trip from Flaine to Samoëns takes {{m:easy.flaine.samoens|w}} lift rides instead of {{m:all.flaine.samoens|w}}.','{}'::text[],'review','loader','routes.after'),
('area:grand-massif','areas','heading',0,'The five resorts compared','{}'::text[],'review','loader','areas.h2'),
('area:grand-massif','areas','line',0,'The five resorts start at very different heights. Morillon''s gondola leaves the village at {{f:F000737}} and the Grand Massif Express leaves Samoëns at {{f:F000742}}, while Flaine''s lifts start at {{f:F000727}}, far above the top of anything at Sixt. Only Flaine climbs past {{f:F000738}} in the map data: the Grandes Platières cable car and the Diamant Noir chair both reach {{f:F000728}}.',array['F000727','F000728','F000737','F000738','F000742']::text[],'review','loader','areas.intro'),
('area:grand-massif','areas','caption',0,'The five resorts of the Grand Massif','{}'::text[],'review','loader','areas.caption'),
('area:grand-massif','areas','line',1,'Resort','{}'::text[],'review','loader','areas.nameLabel'),
('area:grand-massif','areas','line',2,'Resorts','{}'::text[],'review','loader','areas.navLabel'),
('area:grand-massif','areas','line',3,'Linked; the high bowl at the centre of the area','{}'::text[],'review','loader','areas.rows.0.net'),
('area:grand-massif','areas','note',0,'A car free Forum at the foot of the Grandes Platières cable car, with Flaine Forêt, Montsoleil and Le Hameau above it on free shuttles.','{}'::text[],'review','loader','areas.rows.0.note'),
('area:grand-massif','areas','line',4,'Linked to Flaine by the Tête des Saix chair','{}'::text[],'review','loader','areas.rows.1.net'),
('area:grand-massif','areas','note',1,'A lived in village on a sunny shelf; the Kédeuze gondola is its only lift into the area.','{}'::text[],'review','loader','areas.rows.1.note'),
('area:grand-massif','areas','line',5,'Linked over the Saix plateau','{}'::text[],'review','loader','areas.rows.2.net'),
('area:grand-massif','areas','note',2,'A gondola from the village to Morillon 1100, a car free station at Les Esserts, then the Sairon chair.','{}'::text[],'review','loader','areas.rows.2.note'),
('area:grand-massif','areas','line',6,'Linked to Flaine and the Saix plateau','{}'::text[],'review','loader','areas.rows.3.net'),
('area:grand-massif','areas','note',3,'The Grand Massif Express from the village and the Vercland gondola up the valley both reach Samoëns 1600.','{}'::text[],'review','loader','areas.rows.3.note'),
('area:grand-massif','areas','line',7,'Reached on skis by the Cascades; skibus back','{}'::text[],'review','loader','areas.rows.4.net'),
('area:grand-massif','areas','note',4,'Four drags on the Salvagny beginner slopes; the share of easy run counts the lower Cascades, which is red.','{}'::text[],'review','loader','areas.rows.4.note'),
('area:grand-massif','areas','note',5,'Lift heights are the lowest lift base and highest lift top in each resort, from OpenStreetMap lift positions and the Copernicus 90 m elevation model. Easy is the share of piste length graded green or blue in OpenStreetMap; drags are the share of the main lifts.','{}'::text[],'review','loader','areas.note'),
('area:grand-massif','terrain','heading',0,'Blue miles, a few steep corners','{}'::text[],'review','loader','terrain.h2'),
('area:grand-massif','terrain','para',0,'Alti-Mag counts {{f:F000645}} runs: {{f:F000646}} green, {{f:F000647}} blue, {{f:F000648}} red and {{f:F000649}} black. skiresort.com measures {{f:F000527}} of the piste as easy, {{f:F000528}} as intermediate and {{f:F000529}} as difficult, so this is a big intermediate area with its steepest skiing gathered high above Flaine.',array['F000527','F000528','F000529','F000645','F000646','F000647','F000648','F000649']::text[],'review','loader','terrain.paras.0'),
('area:grand-massif','terrain','para',1,'Green and blue reach every resort from every other in the map data. The quick routes are sometimes red: from Flaine the fastest way to Samoëns runs down the Combe de Vernant, and on blue the same trip takes {{m:easy.flaine.samoens|w}} lift rides instead of {{m:all.flaine.samoens|w}}. From Flaine to Morillon the gap is {{m:easy.flaine.morillon|w}} against {{m:all.flaine.morillon|w}}.','{}'::text[],'review','loader','terrain.paras.1'),
('area:grand-massif','terrain','para',2,'The long runs give the place its character. Guide Ski describes the Serpentine as a blue of about seven kilometres from the top of Flaine and the Faust as a red with two sustained walls, and below the Tête des Saix the Marvel run threads spruce forest towards Morillon. The Cascades is the longest of all, regraded from blue to red for its length rather than its pitch, and drops about seventeen hundred metres to Sixt.','{}'::text[],'review','loader','terrain.paras.2'),
('area:grand-massif','terrain','para',3,'The steep ground is high and close to Flaine. The Combe de Gers, marked but never groomed, falls about eight hundred metres on north facing slopes below the Gers drag, with the Onyx and Jais lines down it. The Diamant Noir chair, the Lindars and the Combe de Véret above the bowl give more ungroomed black ground, and Alpine Answers points to the trees above Les Carroz on days of poor light.','{}'::text[],'review','loader','terrain.paras.3'),
('area:grand-massif','terrain','para',4,'Drags are a large part of the lift fleet. In the map data {{f:F000725}} of the {{f:F000724}} main lifts are drags, against {{f:F000741}} of the main lifts at Morillon, where the Coulouvrier and Sairon chairs do most of the climbing.',array['F000724','F000725','F000741']::text[],'review','loader','terrain.paras.4'),
('area:grand-massif','terrain','heading',1,'Lift rides between the resorts, and the grade they need','{}'::text[],'review','loader','terrain.matrixTitle'),
('area:grand-massif','terrain','note',0,'Rows are where the day starts, columns where it goes. Each cell shows the fewest lift rides from the village lifts, on green and blue where that works, from the OpenStreetMap piste grades of October 2026. Sixt and Samoëns are joined by the free skibus, which counts as no lift ride.','{}'::text[],'review','loader','terrain.matrixNote'),
('area:grand-massif','snow','heading',0,'A snowy bowl above low villages','{}'::text[],'review','loader','snow.h2'),
('area:grand-massif','snow','para',0,'The Samoëns tourist office describes most of the slopes as facing north, and Alpine Answers credits the open slopes above Samoëns with holding their snow. The weather model behind the snowfall figures covers the whole area with one grid cell, at 46.0 N 6.75 E, and adjusts it to three heights.','{}'::text[],'review','loader','snow.paras.0'),
('area:grand-massif','snow','para',1,'At the middle height the cell is generous. A typical season between 1991 and 2020 brought {{f:F000813}} of snow at 1,600 m, more than the cells of the Portes du Soleil ({{f:F000628}}), Évasion Mont Blanc ({{f:F000622}}) and La Clusaz ({{f:F000817}}) at the same height. At 2,100 m, close to the top of the Flaine bowl, the typical season brought {{f:F000815}}, against {{f:F000816}} in 1961 to 1990.',array['F000622','F000628','F000813','F000815','F000816','F000817']::text[],'review','loader','snow.paras.1'),
('area:grand-massif','snow','para',2,'The valley villages are another matter. At 1,100 m, the height of Morillon 1100 and Les Carroz, a typical season brought {{f:F000811}} in 1991 to 2020 against {{f:F000812}} in 1961 to 1990, and three of the five lowest seasons in the 76 year record came in a row, from 2022/23 to 2024/25. Samoëns and Morillon lie lower still, close to {{f:F000742|n}} m, so the runs home to the valley are the first to suffer in a poor winter. The high ground held up: at 2,100 m the season of 2023/24 brought more snow than the typical season of 1991 to 2020.',array['F000742','F000811','F000812']::text[],'review','loader','snow.paras.2'),
('area:grand-massif','snow','para',3,'The season follows the height. Flaine opens first, on {{f:F000657|dm}}, and closes last, on {{f:F000658|dm}}; the whole Grand Massif runs from {{f:F000659|dm}} to {{f:F000660|dm}}. Alti-Mag closes the Villages area a week earlier, on {{f:F000662|dm}}, and the Salvagny slopes at Sixt run only until {{f:F000663|dm}}.',array['F000657','F000658','F000659','F000660','F000662','F000663']::text[],'review','loader','snow.paras.3'),
('area:grand-massif','snow','heading',1,'Lift heights by resort','{}'::text[],'review','loader','snow.heightsTitle'),
('area:grand-massif','snow','caption',0,'Lowest lift base to highest lift top in each resort, from OpenStreetMap lift positions and the Copernicus 90 m elevation model.','{}'::text[],'review','loader','snow.heightsCaption'),
('area:grand-massif','snow','heading',2,'Seasonal snowfall at three heights, 1950 to 2026','{}'::text[],'review','loader','snow.chartTitle'),
('area:grand-massif','snow','caption',1,'Snowfall from November to April in the ERA5 reanalysis, via the Open-Meteo historical weather API, for the grid cell at 46.0 N, 6.75 E adjusted to each height. Dots are single seasons; lines are 11 season running means. These are weather model values for the cell, not depths on a piste.','{}'::text[],'review','loader','snow.chartCaption'),
('area:grand-massif','snow','line',0,'Snowfall from November to April in the weather model. Median 1991 to 2020: {{f:F000811}} at 1,100 m, {{f:F000813}} at 1,600 m, {{f:F000815}} at 2,100 m.',array['F000811','F000813','F000815']::text[],'review','loader','snow.chartDesc'),
('area:grand-massif','snow','line',1,'<b>No conditions are reported here yet.</b> Flaine is due to open on {{f:F000657}} and the whole area on {{f:F000659}}. Until live data arrives, the official sources below give open lifts, pistes and forecasts.',array['F000657','F000659']::text[],'review','loader','snow.conditions.status'),
('area:grand-massif','snow','line',2,'Lifts and pistes open','{}'::text[],'review','loader','snow.conditions.items.0.dt'),
('area:grand-massif','snow','line',3,'<a href="https://www.grand-massif.com/en/">Le Grand Massif</a>, <a href="https://www.flaine.com/en/">Flaine</a> and <a href="https://www.samoens.com/en/">Samoëns</a>','{}'::text[],'review','loader','snow.conditions.items.0.dd'),
('area:grand-massif','snow','line',4,'Mountain forecast','{}'::text[],'review','loader','snow.conditions.items.1.dt'),
('area:grand-massif','snow','line',5,'<a href="https://meteofrance.com/meteo-montagne/flaine/741121">Météo-France for Flaine</a>','{}'::text[],'review','loader','snow.conditions.items.1.dd'),
('area:grand-massif','snow','line',6,'Avalanche danger','{}'::text[],'review','loader','snow.conditions.items.2.dt'),
('area:grand-massif','snow','line',7,'<a href="https://meteofrance.com/meteo-montagne">Météo-France bulletins</a> for the Haute-Savoie massifs, published daily in winter','{}'::text[],'review','loader','snow.conditions.items.2.dd'),
('area:grand-massif','snow','line',8,'Terrain beyond the marked pistes is not controlled. The avalanche bulletin and local advice take precedence over anything on this page.','{}'::text[],'review','loader','snow.conditions.safety'),
('area:grand-massif','pass','heading',0,'Which pass, and where to buy it','{}'::text[],'review','loader','pass.h2'),
('area:grand-massif','pass','para',0,'The Grand Massif pass covers all five resorts. A day costs {{f:F000690}} at the ticket office and six days {{f:F000533}}, and the Flaine tourist office lists a discount on passes of six days and more booked by the end of October.',array['F000533','F000690']::text[],'review','loader','pass.paras.0'),
('area:grand-massif','pass','para',1,'Two smaller passes cost less. The Villages pass covers Les Carroz, Morillon, Samoëns and Sixt without Flaine, {{f:F000656}} of piste by Alti-Mag''s count, for {{f:F000704}} for six days, {{diff:F000533,F000704}} less than the full pass. The Flaine pass covers Flaine alone for {{f:F000699}} a day. Each suits a stay at one end of the area; only the full pass takes in the Cascades, which starts in Flaine and finishes in Sixt.',array['F000533','F000656','F000699','F000704']::text[],'review','loader','pass.paras.1'),
('area:grand-massif','pass','para',2,'Children under {{f:F000688|n}} and adults of 75 and over ski free by the day at the ticket office with proof of age, and pay {{f:F000693}} for two to seven days. Beginners in Flaine can buy a pass for the gentle lifts at {{f:F000701}} a day, and Sixt sells its own beginner day at {{f:F000707}}. Walkers ride the Grandes Platières cable car to the top for {{f:F000702}} return.',array['F000688','F000693','F000701','F000702','F000707']::text[],'review','loader','pass.paras.2'),
('area:grand-massif','pass','caption',0,'Local passes against the full pass, adult, 2026/27','{}'::text[],'review','loader','pass.table.caption'),
