('area:grand-massif','pass','note',0,'Sources: <a href="https://www.flaine.com/en/winter/skiing-snowsports/ski-passes/ski-passes.htm">the Flaine tourist office</a>, <a href="https://www.alti-mag.com/domaines-skiables/le-grand-massif">Alti-Mag</a> and <a href="https://www.alti-mag.com/domaines-skiables/villages-grand-massif">Alti-Mag for the Villages</a>.','{}'::text[],'review','loader','pass.table.note'),
('area:grand-massif','pass','heading',1,'What the pass covers','{}'::text[],'review','loader','pass.coverageTitle'),
('area:grand-massif','pass','line',16,'Linked both ways by lift and piste','{}'::text[],'review','loader','pass.coverage.0.label'),
('area:grand-massif','pass','line',17,'Flaine: Forum, Forêt, Montsoleil and Le Hameau','{}'::text[],'review','loader','pass.coverage.0.items.0'),
('area:grand-massif','pass','line',18,'Les Carroz and Les Molliets','{}'::text[],'review','loader','pass.coverage.0.items.1'),
